    &lt;span class="k"&gt;return&lt;/span&gt; &lt;span class="n"&gt;json&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;loads&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;&lt;strong&gt;Why this works&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;The prompt forces the LLM to think step‑by‑step and produce structured JSON, making downstream parsing trivial.
&lt;/li&gt;
&lt;li&gt;By feeding sample rows (just 10) you avoid leaking sensitive data while still giving context for the judge.
&lt;/li&gt;
&lt;li&gt;Using a cheap model keeps per‑query cost under $0.01–$0.02.&lt;/li&gt;
&lt;/ul&gt;




&lt;h2&gt;


  Putting It All Together – Batch Runner
&lt;/h2&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;
python
# batch_evaluator.py
import asyncio
from deterministic_evaluator import evaluate_80_20
from llm_judge import run_judge

async def evaluate_case(case: dict, semaphore: asyncio.Semaphore) -&amp;gt; dict:
    async with semaphore:
        det_scores = evaluate_80_20(
            case["expected_sql"],
            case["llm_sql"],
            case["expected_df"],
            case["llm_df"]
        )

        if det_scores["overall_score"] &amp;gt;= 0.92:
            return {**case, **det_scores, "judge_review": None}

        # Trigger LLM judge
        judge = await run_judge(
            user_query=case["user_query"],
            schema_ddl=case["schema_ddl"],
            expected_sql=case["expected_sql"],
            llm_sql=case["llm_sql"],
            exp_sample_csv=case["expected_df"].head(10).to_csv(index=False),
            llm_sample_csv=case["llm_df"].head(10).to_csv(index=False),
            exp_rows=len(case["expected_df"]),
            llm_rows=len(case["llm_df"]),
            exp_cols=",".join(case["expected_df"].columns),
            llm_cols=",".
